payload.css:
:host { display: block; color: #fff; font: 14px ui-sans-serif, system-ui, sans-serif; }
.settings[hidden] { display: none; }
.settings { position: absolute; inset: 0; z-index: 1; }
.backdrop { position: absolute; inset: 0; background: rgb(0 0 0 / 60%); pointer-events: auto; }
.panel { position: absolute; top: 50%; left: 50%; min-width: 260px; padding: 24px; background: #1b2235; border-radius: 12px; transform: translate(-50%, -50%); }
label { display: block; margin: 16px 0; }
